import{_ as i,a0 as l,w as n,s as m,I as e,x as a,a1 as r,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"如何在Linux上移除文件內的隱私數據 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux上移除文件內的隱私數據 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux上移除文件內的隱私數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux上移除文件內的隱私數據 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140813 How to remove file metadata on Linux","title":"如何在Linux上移除文件內的隱私數據","tag":"201410","desc":""},"relativePath":"201410/20140813 How to remove file metadata on Linux.md","filePath":"[post].md"}'),s={name:"201410/20140813 How to remove file metadata on Linux.md"};function u(f,t,x,g,T,b){const o=l("Link");return n(),m("div",null,[t[25]||(t[25]=e("h1",{id:"如何在linux上移除文件內的隱私數據",tabindex:"-1"},[a("如何在Linux上移除文件內的隱私數據 "),e("a",{class:"header-anchor",href:"#如何在linux上移除文件內的隱私數據","aria-label":"Permalink to “如何在Linux上移除文件內的隱私數據”"},"​")],-1)),t[26]||(t[26]=e("p",null,"典型的數據文件通常關聯着“元數據”，其包含這個文件的描述信息，表現為一系列屬性-值的集合。元數據一般包括創建者名稱、生成文件的工具、文件創建/修改時期、創建位置和編輯歷史等等。幾種流行的元數據標準有 EXIF（圖片）、RDF（web資源）和DOI（數字文檔）等。",-1)),e("p",null,[t[2]||(t[2]=a("雖然元數據在數據管理領域有它的優點，但事實上它會",-1)),r(o,{href:"http://www.theguardian.com/world/2013/sep/30/nsa-americans-metadata-year-documents"},{default:p(()=>[...t[0]||(t[0]=[a("危害",-1)])]),_:1}),t[3]||(t[3]=a("你的隱私。相機圖片中的EXIF格式數據會泄露出可識別的個人信息，比如相機型號、拍攝相關的GPS座標和用户偏愛的照片編輯軟件等。在文檔和電子表格中的元數據包含作者/所屬單位信息和相關的編輯歷史。不一定這麼絕對，但諸如",-1)),r(o,{href:"http://code.google.com/p/metagoofil/"},{default:p(()=>[...t[1]||(t[1]=[a("metagoofil",-1)])]),_:1}),t[4]||(t[4]=a("一類的元數據收集工具在信息收集的過程中常最作為入侵測試的一部分被利用。",-1))]),t[27]||(t[27]=e("p",null,[a("對那些想要從共享數據中擦除一切個人元數據的用户來説，有一些方法從數據文件中移除元數據。你可以使用已有的文檔或圖片編輯軟件，通常有自帶的元數據編輯功能。在這個教程裏，我會介紹一種不錯的、單獨的"),e("strong",null,"元數據清理工具"),a("，其目標只有一個："),e("strong",null,"匿名一切私有元數據"),a("。")],-1)),e("p",null,[r(o,{href:"https://mat.boum.org/"},{default:p(()=>[...t[5]||(t[5]=[a("MAT",-1)])]),_:1}),t[7]||(t[7]=a("（元數據匿名工具箱）是一款專業的元數據清理器，使用Python編寫。它屬於Tor旗下的項目，而且是Live 版的隱私增強操作系統 ",-1)),r(o,{href:"https://tails.boum.org/"},{default:p(()=>[...t[6]||(t[6]=[a("Trails",-1)])]),_:1}),t[8]||(t[8]=a(" 的標配應用。",-1))]),e("p",null,[t[10]||(t[10]=a("與諸如",-1)),r(o,{href:"http://xmodulo.com/2013/08/view-or-edit-pdf-and-image-metadata-from-command-line-on-linux.html"},{default:p(()=>[...t[9]||(t[9]=[a("exiftool",-1)])]),_:1}),t[11]||(t[11]=a("等只能對有限種類的文件類型進行寫入的工具相比，MAT支持從各種各樣的文件中消除元數據：圖片（png、jpg）、文檔（odt、docx、pptx、xlsx和pdf）、歸檔文件（tar、tar.bz2）和音頻（mp3、ogg、flac）等。",-1))]),t[28]||(t[28]=d(`<h3 id="在linux上安裝mat" tabindex="-1">在Linux上安裝MAT <a class="header-anchor" href="#在linux上安裝mat" aria-label="Permalink to “在Linux上安裝MAT”">​</a></h3><p>在基於Debian的系統（Ubuntu或Linux Mint）上，已經打包好MAT，所以安裝很直接：</p><pre><code>$ sudo apt-get install mat
</code></pre><p>在Fedora上，並沒有預先生成的MAT軟件包，所以你需要從源碼生成。這是我在Fedora上生成MAT的步驟（不成功的話，請查看教程底部）：</p><pre><code>$ sudo yum install python-devel intltool python-pdfrw perl-Image-ExifTool python-mutagen
$ sudo pip install hachoir-core hachoir-parser
$ wget https://mat.boum.org/files/mat-0.5.tar.xz
$ tar xf mat-0.5.tar.xz
$ cd mat-0.5
$ python setup.py install 
</code></pre><h3 id="使用mat-gui匿名元數據" tabindex="-1">使用MAT-GUI匿名元數據 <a class="header-anchor" href="#使用mat-gui匿名元數據" aria-label="Permalink to “使用MAT-GUI匿名元數據”">​</a></h3><p>一旦安裝好，通過GUI和命令列都可以使用MAT。輸入這個命令啓動MAT的GUI：</p><pre><code>$ mat-gui
</code></pre><p>嘗試清理一個包含如下內置元數據的實例文檔文件（如private.odt）。</p><p><img src="https://farm6.staticflickr.com/5588/14694815240_22eced1f94_z.jpg" alt=""></p><p>點擊“添加”按鈕來添加需要清理的文件到MAT中。一旦載入文件，點擊“確認”按鈕對所有隱藏的元數據信息進行掃描。</p><p><img src="https://farm4.staticflickr.com/3874/14694958067_00694d9d1f_z.jpg" alt=""></p><p>只要元數據被MAT檢測到，“State”狀態就會被標記成“Dirty”。雙擊文件可以查看檢測到的元數據。</p><p><img src="https://farm4.staticflickr.com/3861/14694815160_cda63bb8d8_z.jpg" alt=""></p><p>點擊“清理”按鈕來清除文件中的元數據。MAT會自動清空文件中的所有私有元數據字段。</p><p><img src="https://farm6.staticflickr.com/5554/14694815220_40918f680f_z.jpg" alt=""></p><p>清除後的狀態中不包含任何私有可辨識的痕跡：</p><p><img src="https://farm6.staticflickr.com/5591/14881486215_83808b6aaf_z.jpg" alt=""></p><h3 id="從命令列匿名元數據" tabindex="-1">從命令列匿名元數據 <a class="header-anchor" href="#從命令列匿名元數據" aria-label="Permalink to “從命令列匿名元數據”">​</a></h3><pre><code>$ mat -c .
</code></pre><p>正如前面提到的，另一種調用MAT的方式是從命令列，使用mat命令可達到。</p><p>為了檢查任何敏感的元數據，先前往文件所在的目錄，然後運行：</p><pre><code>$ mat -c .
</code></pre><p>這樣會掃描當前目錄和其子目錄下的所有文件，並報告它們的狀態（已清理或未清理）。</p><p><img src="https://farm6.staticflickr.com/5564/14878449991_cf9d605e6d_o.png" alt=""></p><p>你可以使用“-d”選項來查看檢測到的真實元數據：</p><pre><code>$ mat -d &lt;input_file&gt; 
</code></pre><p><img src="https://farm6.staticflickr.com/5558/14901361173_0e587329f5_z.jpg" alt=""></p><p>如果不為mat命令提供任何選項，默認操作會移除文件的元數據。如果要在清理的過程中保留原始文件的備份，使用“-b”選項。下面命令會清除所有文件的元數據，並將原始文件存儲為“*.bak”文件。</p><pre><code>$ mat -b . 
</code></pre><p><img src="https://farm6.staticflickr.com/5591/14694850169_1cf7562657_z.jpg" alt=""></p><p>查看所支持的文件類型，請運行：</p><pre><code>$ mat -l 
</code></pre><p><img src="https://farm6.staticflickr.com/5588/14901361153_e59ab7b684_z.jpg" alt=""></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>當前我在Fedora上使用編譯版本的MAT遇到了下列問題。當我嘗試在Fedora清除歸檔/文檔文件的元數據時（如<em>.gz、</em>.odt、*.docx），MAT因為下列錯誤失敗。如果你知道如何解決這個問題，請在評論裏回覆我。</p><pre><code>  File &quot;/usr/lib64/python2.7/zipfile.py&quot;, line 305, in __init__
    raise ValueError(&#39;ZIP does not support timestamps before 1980&#39;)
ValueError: ZIP does not support timestamps before 1980
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>MAT是一款簡單但非常好用的工具，用來預防從元數據中無意泄露私人數據。請注意如果有必要，文件內容也需要保護。MAT能做的是消除與文件相關的元數據，但並不會對文件本身進行任何操作。簡而言之，MAT是一名救生員，因為它可以處理大多數常見的元數據移除，但不應該只指望它來保證你的隱私。[譯者注：養成良好的隱私保護意識和習慣才是最好的方法]</p><hr>`,40)),e("p",null,[t[13]||(t[13]=a("via: ",-1)),r(o,{href:"http://xmodulo.com/2014/08/remove-file-metadata-linux.html"},{default:p(()=>[...t[12]||(t[12]=[a("http://xmodulo.com/2014/08/remove-file-metadata-linux.html",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=a("作者：",-1)),r(o,{href:"http://xmodulo.com/author/nanni"},{default:p(()=>[...t[14]||(t[14]=[a("Dan Nanni",-1)])]),_:1}),t[18]||(t[18]=a(" 譯者：",-1)),r(o,{href:"https://github.com/KayGuoWhu"},{default:p(()=>[...t[15]||(t[15]=[a("KayGuoWhu",-1)])]),_:1}),t[19]||(t[19]=a(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[16]||(t[16]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=a("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[20]||(t[20]=[a("LCTT",-1)])]),_:1}),t[23]||(t[23]=a(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:p(()=>[...t[21]||(t[21]=[a("Linux中國",-1)])]),_:1}),t[24]||(t[24]=a(" 榮譽推出",-1))])])}const A=i(s,[["render",u]]);export{M as __pageData,A as default};
